export function getEventArticleBySlug(language: SiteLanguage, slug: string | undefined) {
  return eventArticles[language].find((article) => article.slug === slug);
}

export function getArticleSlugForEventType(eventType: EventType | undefined) {
  return eventType ? eventArticleSlugByEventType[eventType] : undefined;
}

export function hasEventArticle(eventType: EventType | undefined) {
  return Boolean(getArticleSlugForEventType(eventType));
}
